package ru.mcsa.translator;
import java.util.*;import java.util.jar.*;import java.nio.charset.StandardCharsets;
import org.yaml.snakeyaml.*;import org.yaml.snakeyaml.constructor.SafeConstructor;
public final class ResourceContracts {
 private static boolean equal(Object a,Object b){if(a instanceof Number&&b instanceof Number)return Double.compare(((Number)a).doubleValue(),((Number)b).doubleValue())==0;if(a instanceof Map&&b instanceof Map){Map<?,?> x=(Map<?,?>)a,y=(Map<?,?>)b;if(!x.keySet().equals(y.keySet()))return false;for(Object key:x.keySet())if(!equal(x.get(key),y.get(key)))return false;return true;}if(a instanceof List&&b instanceof List){List<?> x=(List<?>)a,y=(List<?>)b;if(x.size()!=y.size())return false;for(int i=0;i<x.size();i++)if(!equal(x.get(i),y.get(i)))return false;return true;}return Objects.equals(a,b);}
 public static void main(String[] args)throws Exception{int count=0;try(JarFile jar=new JarFile(args[0])){Enumeration<JarEntry> entries=jar.entries();while(entries.hasMoreElements()){JarEntry e=entries.nextElement();if(!e.getName().endsWith(".yml"))continue;String text=new String(jar.getInputStream(e).readAllBytes(),StandardCharsets.UTF_8);Object expected=new Yaml(new SafeConstructor(new LoaderOptions())).load(text);Object actual=ru.mcsa.bukkit.Yaml.parse(text);if(!equal(expected,actual))throw new AssertionError(e.getName()+": YAML различается");String encoded=ru.mcsa.bukkit.Yaml.write(actual);if(!equal(actual,ru.mcsa.bukkit.Yaml.parse(encoded)))throw new AssertionError(e.getName()+": YAML не пережил запись");count++;}}System.out.println("PASS: "+count+" ресурсов YAML совпали с безопасным эталонным парсером; классы плагина не запускались");}
}
